  const result = spawnSync(process.execPath, [renderer], { input: request, encoding: "utf8" });

  assert.equal(result.status, 0, result.stderr);
  assert.match(result.stdout, /^Finding: The renderer preserves this semantic summary\.$/m);
  assert.doesNotMatch(result.stdout, /^Summary:/m);

  const encoded = result.stdout.match(/^<!-- skill-rails-next:verify-record:([A-Za-z0-9_-]+) -->$/m)?.[1];
  assert.ok(encoded, "rendered record retains its encoded semantic answer");
  assert.deepEqual(JSON.parse(Buffer.from(encoded, "base64url").toString("utf8")), answer);
});

#!/usr/bin/env node
import { resolve } from "node:path";
import { buildTargets, planTargetBuild } from "./build.mjs";
import { checkTarget } from "./check.mjs";
import { toResultError, fail } from "./errors.mjs";
import { inspectGraph } from "./inspect.mjs";
import { loadSourceGraph } from "./validate.mjs";

function parse(argv) {
  const [command, ...rest] = argv;
  const values = {};
  for (let index = 0; index < rest.length;) {
    const key = rest[index];
    if (!key?.startsWith("--")) fail("ARGUMENT_INVALID", `Invalid argument near ${key ?? "<end>"}.`, "Use documented named arguments.");
    if (Object.hasOwn(values, key)) fail("ARGUMENT_INVALID", `Duplicate argument ${key}.`, "Pass each argument once.");
    if (key === "--json") { values[key] = true; index += 1; continue; }
    if (index + 1 >= rest.length || rest[index + 1].startsWith("--")) fail("ARGUMENT_INVALID", `${key} requires a value.`, "Provide one value for the argument.");
    values[key] = rest[index + 1];
    index += 2;
  }
  return { command, values };
}

function allow(values, allowed) {
  for (const key of Object.keys(values)) if (!allowed.includes(key)) fail("ARGUMENT_INVALID", `Unknown argument ${key}.`, "Remove arguments outside the command contract.");
}

async function main() {
  const { command, values } = parse(process.argv.slice(2));
  if (command === "build") {
    allow(values, ["--source", "--target", "--out", "--out-root"]);
    if (!values["--source"]) fail("ARGUMENT_INVALID", "build requires --source.", "Provide the canonical source package manifest.");
    const single = Boolean(values["--target"] || values["--out"]);
    if (single !== Boolean(values["--target"] && values["--out"]) || (single && values["--out-root"]) || (!single && !values["--out-root"])) fail("ARGUMENT_INVALID", "Choose either --target with --out, or --out-root.", "Use one documented build form.");
    return buildTargets(await loadSourceGraph(values["--source"]), { target: values["--target"], out: values["--out"], outRoot: values["--out-root"] });
  }
  if (command === "check") {
    allow(values, ["--source", "--target", "--out"]);
    if (!values["--out"]) fail("ARGUMENT_INVALID", "check requires --out.", "Provide the exact generated target directory.");
    let plan;
    if (values["--source"] || values["--target"]) {
      if (!values["--source"] || !values["--target"]) fail("ARGUMENT_INVALID", "Source-current check requires both --source and --target.", "Provide both canonical source and exact targetId.");
      plan = await planTargetBuild(await loadSourceGraph(values["--source"]), values["--target"]);
    }
    return checkTarget(resolve(values["--out"]), plan);
  }
  if (command === "inspect") {
    allow(values, ["--source", "--id", "--path", "--json"]);
    if (!values["--source"] || Boolean(values["--id"]) === Boolean(values["--path"]) || values["--json"] !== true) fail("ARGUMENT_INVALID", "inspect requires --source, exactly one of --id/--path, and --json.", "Use the documented exact inspect form.");
    return inspectGraph(await loadSourceGraph(values["--source"]), { id: values["--id"], path: values["--path"] });
  }
  fail("ARGUMENT_INVALID", `Unknown command: ${command ?? "<none>"}.`, "Use build, check, or inspect.");
}

try {
  process.stdout.write(`${JSON.stringify(await main())}\n`);
} catch (error) {
  process.stdout.write(`${JSON.stringify(toResultError(error))}\n`);
  process.exitCode = 1;
}

import { mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { basename, dirname, relative, resolve } from "node:path";
import { randomUUID } from "node:crypto";
import { canonicalJson, compareCodePoint, sha256, treeSha256 } from "./canonicalize.mjs";
import { fail } from "./errors.mjs";
import { assertArtifactIntegrity } from "./check.mjs";
import { buildHeadingIndex } from "./heading-index.mjs";

const COMMON_RUNTIME_ARTIFACTS = new Map([
  ["scripts/runtime/common.mjs", "src/runtime/common.mjs"],
  ["scripts/runtime/integrity.mjs", "src/runtime/integrity.mjs"],
]);

function withGeneratedMarker(entry, logicalSource) {
  const marker = `<!-- generated; do not edit; source: ${logicalSource}; receipt: .skill-rails-build.json -->`;
  if (!entry.startsWith("---\n")) fail("ENTRY_INVALID", `${logicalSource} must start with YAML frontmatter.`, "Add a closed skill frontmatter block.");
  const end = entry.indexOf("\n---\n", 4);
  if (end < 0) fail("ENTRY_INVALID", `${logicalSource} has no closing YAML frontmatter delimiter.`, "Close the frontmatter with --- on its own line.");
  return `${entry.slice(0, end + 5)}${marker}\n${entry.slice(end + 5)}`;
}

function artifactPathForModule(id) {
  return `references/${id}.md`;
}

function generatedTargetConfig(graph, item) {
  const { target } = item;
  return {
    schemaVersion: 1,
    packageId: graph.manifest.packageId,
    packageVersion: graph.manifest.packageVersion,
    targetId: target.targetId,
    mode: target.mode,
    imports: target.imports.map((id) => ({ id, path: artifactPathForModule(id) })),
    headingIndex: target.headingIndex ? `references/${target.headingIndex}.index.json` : null,
    fallbackReference: target.fallbackModule ? "references/fallback.md" : null,
    domainConfig: target.mode === "prose" ? null : "config/domain.json",
    domainConfigSchema: target.mode === "prose" ? null : "config/domain.schema.json",
    packet: target.packet ? "config/packet.json" : null,
    observer: target.observer ? "scripts/domain/observer.mjs" : null,
    renderer: target.renderer ? "scripts/domain/renderer.mjs" : null,
    answerContract: target.mode === "prose" ? null : `contracts/${basename(target.answerContract)}`,
    declaredInputs: target.declaredInputs ?? [],
    declaredOutput: target.declaredOutput ?? null,
    outputMode: target.outputMode ?? null,
    regionBootstrap: target.regionBootstrap ?? null,
  };
}

function addSource(sources, id, item) {
  sources.push({ id, path: item.path, sha256: sha256(item.bytes) });
}

export async function planTargetBuild(graph, targetId) {
  const item = graph.targets.get(targetId);
  if (!item) fail("TARGET_NOT_FOUND", `Unknown targetId: ${targetId}`, "Choose an exact targetId declared by the source package.");
  const artifacts = new Map();
  const sources = [];
  addSource(sources, "source-package", { path: relative(graph.rootReal, graph.manifestPath).replaceAll("\\", "/"), bytes: graph.manifestBytes });
  addSource(sources, `target:${targetId}`, { path: item.path, bytes: item.bytes });
  const entry = item.files.get("entry");
  addSource(sources, "entry", entry);
  artifacts.set("SKILL.md", Buffer.from(withGeneratedMarker(entry.text, entry.path), "utf8"));

  for (const id of item.target.imports) {
    const module = graph.modules.get(id);
    addSource(sources, `module:${id}`, module);
    artifacts.set(artifactPathForModule(id), module.bytes);
  }
  if (item.target.headingIndex) {
    const module = graph.modules.get(item.target.headingIndex);
    artifacts.set(`references/${item.target.headingIndex}.index.json`, buildHeadingIndex(module));
  }
  if (item.target.fallbackModule) {
    const module = graph.modules.get(item.target.fallbackModule);
    if (!sources.some((source) => source.id === `module:${module.id}`)) addSource(sources, `module:${module.id}`, module);
    artifacts.set("references/fallback.md", module.bytes);
  }

  artifacts.set("config/target.json", Buffer.from(`${canonicalJson(generatedTargetConfig(graph, item))}\n`, "utf8"));
  if (item.target.mode !== "prose") {
    const mappings = [
      ["domainConfig", "config/domain.json"],
      ["domainConfigSchema", "config/domain.schema.json"],
      ...(item.target.packet ? [["packet", "config/packet.json"]] : []),
      ["renderer", "scripts/domain/renderer.mjs"],
      ["answerContract", `contracts/${basename(item.target.answerContract)}`],
    ];
    if (item.target.observer) mappings.push(["observer", "scripts/domain/observer.mjs"]);
    for (const [role, destination] of mappings) {
      const source = item.files.get(role);
      addSource(sources, role, source);
      artifacts.set(destination, source.bytes);
    }
  }

  const runtimeArtifacts = new Map(COMMON_RUNTIME_ARTIFACTS);
  runtimeArtifacts.set("scripts/run.mjs", item.target.mode === "prose" ? "src/runtime/run-check.mjs" : item.target.mode === "record-only" ? "src/runtime/run-record.mjs" : "src/runtime/run.mjs");
  if (item.target.mode === "prepare-record") {
    runtimeArtifacts.set("scripts/runtime/prepare.mjs", "src/runtime/prepare.mjs");
  }
  if (item.target.mode !== "prose") {
    runtimeArtifacts.set("scripts/runtime/exchange.mjs", "src/runtime/exchange.mjs");
    runtimeArtifacts.set("scripts/runtime/record.mjs", "src/runtime/record.mjs");
  }
  if (item.target.mode === "record-only") runtimeArtifacts.set("scripts/runtime/initialize-record.mjs", "src/runtime/initialize-record.mjs");
  for (const [destination, source] of runtimeArtifacts) {
    const bytes = await readFile(resolve(graph.repositoryRoot, source));
    artifacts.set(destination, bytes);
    addSource(sources, `runtime:${destination}`, { path: source, bytes });
  }
  const contractNames = ["build-receipt.schema.json"];
  if (item.target.mode !== "prose") contractNames.push("record-exchange.schema.json");
  if (item.target.packet) contractNames.push("packet-kernel.schema.json", "observed-facts.schema.json", "prepared-work.schema.json");
  for (const name of contractNames) {
    const sourcePath = `contracts/${name}`;
    const bytes = await readFile(resolve(graph.repositoryRoot, sourcePath));
    artifacts.set(sourcePath, bytes);
    addSource(sources, `contract:${name}`, { path: sourcePath, bytes });
  }

  const artifactRows = [...artifacts.entries()]
    .sort(([left], [right]) => compareCodePoint(left, right))
    .map(([path, bytes]) => ({ path, sha256: sha256(bytes) }));
  const receipt = {
    schemaVersion: 1,
    coreVersion: graph.coreVersion,
    packageId: graph.manifest.packageId,
    packageVersion: graph.manifest.packageVersion,
    targetId,
    sources: sources.sort((a, b) => compareCodePoint(a.path, b.path) || compareCodePoint(a.id, b.id)),
    artifacts: artifactRows,
    imports: [...item.target.imports],
    treeSha256: treeSha256(artifacts),
  };
  return { graph, item, artifacts, receipt, receiptBytes: Buffer.from(`${canonicalJson(receipt)}\n`, "utf8") };
}

async function exists(path) {
  try { await stat(path); return true; } catch (error) { if (error?.code === "ENOENT") return false; throw error; }
}

async function materialize(plan, destination) {
  const exact = resolve(destination);
  const parent = dirname(exact);
  await mkdir(parent, { recursive: true });
  if (await exists(exact)) {
    await assertArtifactIntegrity(exact, "GENERATED_ARTIFACT_MODIFIED");
  }
  const token = randomUUID();
  const stage = resolve(parent, `.${basename(exact)}.stage-${token}`);
  const backup = resolve(parent, `.${basename(exact)}.backup-${token}`);
  try {
    await mkdir(stage);
    for (const [path, bytes] of [...plan.artifacts.entries()].sort(([a], [b]) => compareCodePoint(a, b))) {
      const output = resolve(stage, ...path.split("/"));
      await mkdir(dirname(output), { recursive: true });
      await writeFile(output, bytes);
    }
    await writeFile(resolve(stage, ".skill-rails-build.json"), plan.receiptBytes);
    await assertArtifactIntegrity(stage);
    if (await exists(exact)) await rename(exact, backup);
    try {
      await rename(stage, exact);
    } catch (error) {
      if (await exists(backup)) await rename(backup, exact);
      throw error;
    }
    await rm(backup, { recursive: true, force: true });
  } finally {
    await rm(stage, { recursive: true, force: true });
  }
  return { targetId: plan.receipt.targetId, output: exact, treeSha256: plan.receipt.treeSha256 };
}

export async function buildTargets(graph, options) {
  const selected = options.target ? [options.target] : [...graph.targets.keys()].sort(compareCodePoint);
  if (options.target && !options.out) fail("ARGUMENT_INVALID", "--target requires --out.", "Provide one exact target output directory.");
  if (!options.target && !options.outRoot) fail("ARGUMENT_INVALID", "Building all targets requires --out-root.", "Provide the distribution root.");
  const plans = [];
  for (const targetId of selected) plans.push(await planTargetBuild(graph, targetId));
  const outputs = [];
  for (const plan of plans) {
    const destination = options.target ? options.out : resolve(options.outRoot, "skills", plan.receipt.targetId);
    outputs.push(await materialize(plan, destination));
  }
  return { schemaVersion: 1, status: "BUILT", outputs };
}

import { lstat, readFile, readdir } from "node:fs/promises";
import { relative, resolve } from "node:path";
import { canonicalJson, compareCodePoint, sha256, treeSha256 } from "./canonicalize.mjs";
import { fail } from "./errors.mjs";

async function walk(root, current = root) {
  const files = [];
  for (const entry of await readdir(current, { withFileTypes: true })) {
    const physical = resolve(current, entry.name);
    if (entry.isSymbolicLink()) fail("ARTIFACT_INTEGRITY_FAILED", "Generated target contains a symbolic link.", "Rebuild the target from canonical source.");
    if (entry.isDirectory()) files.push(...await walk(root, physical));
    else if (entry.isFile()) files.push(relative(root, physical).replaceAll("\\", "/"));
    else fail("ARTIFACT_INTEGRITY_FAILED", "Generated target contains a non-regular artifact.", "Rebuild the target from canonical source.");
  }
  return files.sort(compareCodePoint);
}

export async function readReceipt(targetRoot) {
  let receipt;
  try { receipt = JSON.parse(await readFile(resolve(targetRoot, ".skill-rails-build.json"), "utf8")); }
  catch { fail("ARTIFACT_INTEGRITY_FAILED", "The generated build receipt is missing or invalid.", "Rebuild the target from canonical source."); }
  if (receipt?.schemaVersion !== 1) fail("UNSUPPORTED_VERSION", "The generated receipt version is unsupported.", "Rebuild with a compatible core.");
  if (!Array.isArray(receipt.artifacts) || typeof receipt.treeSha256 !== "string") fail("ARTIFACT_INTEGRITY_FAILED", "The generated build receipt shape is invalid.", "Rebuild the target from canonical source.");
  return receipt;
}

export async function assertArtifactIntegrity(targetRoot, mismatchCode = "ARTIFACT_INTEGRITY_FAILED") {
  const root = resolve(targetRoot);
  const receipt = await readReceipt(root);
  const expectedPaths = receipt.artifacts.map((item) => item.path).sort(compareCodePoint);
  const actualPaths = (await walk(root)).filter((path) => path !== ".skill-rails-build.json");
  if (canonicalJson(actualPaths) !== canonicalJson(expectedPaths)) {
    fail(mismatchCode, "Generated artifact paths differ from the receipt.", "Rebuild the target from canonical source; do not merge generated edits.", { expectedPaths, actualPaths });
  }
  const artifacts = new Map();
  for (const expected of receipt.artifacts) {
    const physical = resolve(root, ...expected.path.split("/"));
    const stats = await lstat(physical);
    if (!stats.isFile()) fail("ARTIFACT_INTEGRITY_FAILED", `${expected.path} is not a regular file.`, "Rebuild the target from canonical source.");
    const bytes = await readFile(physical);
    const actual = sha256(bytes);
    if (actual !== expected.sha256) fail(mismatchCode, `${expected.path} differs from the receipt.`, "Rebuild the target from canonical source; do not merge generated edits.", { path: expected.path, expected: expected.sha256, actual });
    artifacts.set(expected.path, bytes);
  }
  const actualTree = treeSha256(artifacts);
  if (actualTree !== receipt.treeSha256) fail(mismatchCode, "Generated tree hash differs from the receipt.", "Rebuild the target from canonical source; do not merge generated edits.");
  return receipt;
}

export async function checkTarget(targetRoot, expectedPlan = undefined) {
  const receipt = await assertArtifactIntegrity(targetRoot, "GENERATED_ARTIFACT_MODIFIED");
  const sourceCurrent = expectedPlan === undefined ? null : canonicalJson(receipt.artifacts) === canonicalJson(expectedPlan.receipt.artifacts)
    && receipt.treeSha256 === expectedPlan.receipt.treeSha256
    && canonicalJson(receipt.sources) === canonicalJson(expectedPlan.receipt.sources);
  return {
    schemaVersion: 1,
    status: "CHECKED",
    targetId: receipt.targetId,
    artifactIntact: true,
    sourceCurrent,
    remoteLatest: null,
    treeSha256: receipt.treeSha256,
  };
}

